#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2.GameContent.Buffs;
using MVZ2.GameContent.Buffs.Entities;
using MVZ2.Vanilla.Enemies;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using PVZEngine;
using PVZEngine.Auras;
using PVZEngine.Buffs;
using PVZEngine.Collisions;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Modifiers;

namespace MVZ2.GameContent.Enemies
{
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.bubble_Carry)]
    public class Bubble_Carry : EntityBehaviourDefinition
    {
        public Bubble_Carry(string nsp, string name) : base(nsp, name)
        {
            AddAura(new CarryAura());
            AddModifier(new IntModifier(EngineEntityProps.COLLISION_MASK_FRIENDLY, IntegerOperator.BitOr, PROP_COLLISION_MASK));
        }
        public override void Update(Entity entity)
        {
            base.Update(entity);
            if (entity.Parent.ExistsAndAlive())
            {
                DragParent(entity, entity.Parent);
                SetCollisionMask(entity, 0);
            }
            else
            {
                SetCollisionMask(entity, EntityCollisionHelper.MASK_ENEMY);
            }
        }
        public override void PostCollision(EntityCollision collision, int state)
        {
            base.PostCollision(collision, state);
            var bubble = collision.Entity;
            if (bubble.Parent.ExistsAndAlive())
                return;
            var other = collision.Other;
            if (!CanBeCarried(other))
                return;
            Carry(bubble, other);
        }
        public static bool CanBeCarried(Entity entity)
        {
            return !entity.CannotBeCarriedByOtherEnemy() && entity.Type == EntityTypes.ENEMY && entity.GetMass() <= VanillaMass.MEDIUM && !entity.HasBuff<CarriedByBalloonBuff>();
        }
        public static void Carry(Entity entity, Entity parent)
        {
            entity.SetParent(parent);
        }
        public static void DragParent(Entity entity, Entity parent)
        {
            parent.SetCenter(entity.GetCenter());
        }
        public static void SetCollisionMask(Entity entity, int value) => entity.SetProperty(PROP_COLLISION_MASK, value);
        public static int GetCollisionMask(Entity entity) => entity.GetProperty<int>(PROP_COLLISION_MASK);
        public static readonly PropertyMeta<int> PROP_COLLISION_MASK = new VanillaEntityPropertyMeta<int>("collision_mask");
        public class CarryAura : AuraEffectDefinition
        {
            public CarryAura() : base(VanillaBuffID.Entity.carriedByBalloon, 1)
            {
            }

            public override void GetAuraTargets(AuraEffect auraEffect, List<IBuffTarget> results)
            {
                var source = auraEffect.Source.GetEntity();
                if (source == null)
                    return;
                if (source.Parent.ExistsAndAlive())
                {
                    results.Add(source.Parent);
                }
            }
        }
    }
}
